window.t = function (key, vars) {
  var lang = window.__supLang || "en";
  var table = window.STR[lang] || window.STR.en;
  var out = table[key];
  if (out == null) out = window.STR.en[key];
  if (out == null) return key;
  if (vars) {
    Object.keys(vars).forEach(function (k) {
      out = out.replace(new RegExp("\\{" + k + "\\}", "g"), vars[k]);
    });
  }
  return out;
};
